class Solution {
public:
    vector<bool> kidsWithCandies(vector<int>& candies, int extraCandies) {
        int max_val = 0;
        for (int candy : candies) {
            if (candy > max_val) {
                max_val = candy;
            }
        }

        int n = candies.size();
        vector<bool> ans(n);
        for (int i = 0; i < n; i++) {
            ans[i] = (candies[i] + extraCandies >= max_val);
        }

        return ans;
    }
};

